//! The generated header (V27): the first line of every `#`-comment file a
//! tool generates, so a reader knows not to edit it by hand.

#[cfg(test)]
mod tests;

/// The header line for files `tool` generates from `config`, newline
/// included: `# generated by <tool> gen from <config>; do not edit`.
#[must_use]
pub fn header(tool: &str, config: &str) -> String {
    let _ = (tool, config);
    String::new()
}
